export type Input = void

export type Output = f64

export default function (in: Input): Output {
  const x: f64 = 0

  return (x = 1) % x
}

export type Input = void

export type Output = f64

export default function (in: Input): Output {
  const x: f64 = 1

  return x % (x = 2)
}

export type Input = void

export type Output = f64

export default function (in: Input): Output {
  return x % (x = 1)
}

export type Input = void

export type Output = f64

export default function (in: Input): Output {
  return (y = 1) % y
}
